import curses
import random

MOVES = {curses.KEY_UP: (-1, 0), curses.KEY_DOWN: (1, 0),
         curses.KEY_LEFT: (0, -1), curses.KEY_RIGHT: (0, 1)}

def main(screen):
    screen.keypad(True)
    screen.timeout(120)
    height, width = screen.getmaxyx()
    if height < 5 or width < 10:
        return
    row, col = height // 2, width // 2
    dr, dc = 0, 1
    body = [(row, col)]
    food = None
    score = 0

    def spawn_food():
        nonlocal food
        while True:
            food = (random.randint(1, height - 2), random.randint(1, width - 2))
            if food not in body:
                break

    def draw():
        screen.erase()
        screen.addnstr(0, 0, f'Score: {score}', width - 1)
        for r, c in body:
            screen.addch(r, c, '#')
        if food:
            screen.addch(food[0], food[1], '*')
        screen.refresh()

    def move():
        nonlocal row, col, body, food, score
        nr, nc = row + dr, col + dc
        if not (1 <= nr < height - 1 and 0 <= nc < width - 1) or (nr, nc) in body:
            screen.addnstr(0, 0, 'Game over', width - 1)
            screen.refresh()
            screen.getch()
            return False
        body.insert(0, (nr, nc))
        if (nr, nc) == food:
            score += 1
            spawn_food()
        else:
            body.pop()
        return True

    spawn_food()
    while True:
        draw()
        key = screen.getch()
        if key == ord('q'):
            return
        dr, dc = MOVES.get(key, (dr, dc))
        if not move():
            return

if __name__ == '__main__':
    curses.wrapper(main)
